function UIFishPoolAutoChooseFrequencyDialog:InitData()
    self._needId = 0
    local num = -1
    local t = FishingUtils.GetFishingPropsList(self._curFishingPlaceId)
    for k, v in pairs(t) do
        --不是基础道具
        if not FishingUtils.IsBaseProps(v) then
            local dojo = FishingUtils.GetFishingGoodsDojo(v)
            if dojo then
                local type = GoodsUtils.GetIdType(v)
                if type == Constants.IDType.GoodsReel or type == Constants.IDType.GoodsFishingRod then
                    local isAutoFix = (checkNumber(KCookie.Get("FishAutoFix")) == 1)
                    if isAutoFix then
                    else
                        num = (num < checkNumber(dojo.durability) and num >= 0) and num or checkNumber(dojo.durability)
                    end
                elseif type == Constants.IDType.GoodsBait or type == Constants.IDType.GoodsFishingLine then
                    num = (num < checkNumber(dojo.num) and num >= 0) and num or checkNumber(dojo.num)
                end
            else
                --找不到一律按0处理
                num = 0
            end

            if num == 0 and self._needId  == 0 then 
                self._needId  = v
            end
        end
    end
    if num <= -1 then
        num = checkNumber(FishingUtils.GetMaxAutoNum())
    end

    local currencyId = FishingUtils.GetCurUseCurrency(self._curFishingPlaceId)
    local currencyNum = GoodsUtils.GetThingNo(currencyId)
    if currencyNum < num then
        num = currencyNum
        if num == 0 and self._needId  == 0 then 
            self._needId  = currencyId
        end
    end

    self._maxNum = num
    self._targetMaxNum = num

    if self._maxNum == 0 then
        self._maxNum = 1
    end
    if self._maxNum >= checkNumber(FishingUtils.GetMaxAutoNum()) then
        self._maxNum = checkNumber(FishingUtils.GetMaxAutoNum())
    end

    if checkNumber(self._curNum) >= self._maxNum  then
        self._curNum = self._maxNum
    elseif checkNumber(self._curNum) <= 1 then
        self._curNum = 1
    end
end

