end

function UIFishPoolAutoChooseFrequencyDialog:OnBtnFrameNode()
    local num = checkNumber(KCookie.Get("FishAutoFix"))
    if num == 1 then
        KCookie.Set("FishAutoFix", 0)
    else
        KCookie.Set("FishAutoFix", 1)
    end

    self:FillAutoFixInfo()

    self:InitData()
    self._curNum = math.min(self._curNum, self._maxNum)
    self:RefreshSelectNum()
end


