function UIFishPoolAutoChooseFrequencyDialog:OnBtnFish()
    if checkNumber(self._targetMaxNum) <= 0 then
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._needId)
        if vo then
            GameUtils.Toast(localize("_name_不足", {_name_ = vo.name}))
        end
        return
    end
    if checkNumber(self._curNum) < 1 then
        GameUtils.Toast(localize("道具不足或渔具耐久不足"))
        return
    end

    fishingComponent:AutoFishReq(self._curNum)
    UIModule.BackDialog()
end

